CREATE TABLE users (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(120) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('SELLER','BUYER','ADMIN') NOT NULL, verified BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE properties (id BIGINT PRIMARY KEY AUTO_INCREMENT, seller_id BIGINT NOT NULL, title VARCHAR(180) NOT NULL, description TEXT NOT NULL, property_type VARCHAR(40) NOT NULL, city VARCHAR(80) NOT NULL, locality VARCHAR(120), address VARCHAR(255), postal_code VARCHAR(20), area DECIMAL(12,2) NOT NULL, bedrooms INT, bathrooms INT, furnishing VARCHAR(40), property_age INT, amenities VARCHAR(1000), expected_price DECIMAL(15,2), estimated_low DECIMAL(15,2), estimated_high DECIMAL(15,2), workflow_status VARCHAR(40) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (seller_id) REFERENCES users(id));
CREATE TABLE resale_listings (id BIGINT PRIMARY KEY AUTO_INCREMENT, property_id BIGINT NOT NULL UNIQUE, asking_price DECIMAL(15,2) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'PUBLISHED', published_at TIMESTAMP NULL, FOREIGN KEY (property_id) REFERENCES properties(id));
CREATE TABLE favorites (user_id BIGINT NOT NULL, listing_id BIGINT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id, listing_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(listing_id) REFERENCES resale_listings(id));
CREATE TABLE purchase_requests (id BIGINT PRIMARY KEY AUTO_INCREMENT, buyer_id BIGINT NOT NULL, listing_id BIGINT NOT NULL, proposed_price DECIMAL(15,2), message VARCHAR(1000), status VARCHAR(30) NOT NULL DEFAULT 'SUBMITTED', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(buyer_id) REFERENCES users(id), FOREIGN KEY(listing_id) REFERENCES resale_listings(id));
CREATE TABLE acquisition_offers (id BIGINT PRIMARY KEY AUTO_INCREMENT, property_id BIGINT NOT NULL, admin_id BIGINT NOT NULL, amount DECIMAL(15,2) NOT NULL, explanation VARCHAR(1000), valid_until DATE NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'ISSUED', FOREIGN KEY(property_id) REFERENCES properties(id), FOREIGN KEY(admin_id) REFERENCES users(id));
CREATE TABLE audit_logs (id BIGINT PRIMARY KEY AUTO_INCREMENT, actor_id BIGINT, entity_type VARCHAR(50) NOT NULL, entity_id BIGINT NOT NULL, action VARCHAR(80) NOT NULL, reason VARCHAR(1000), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_properties_status_city ON properties(workflow_status, city);
CREATE INDEX idx_listings_status ON resale_listings(status);
